    /// realistic GitHub Actions shape: `REDACTED`)
    /// must not survive `CommandOutput::redacted_stderr` -- this is the
    /// single shared implementation every crate-level `redact_*_stderr`
    /// call site now delegates to instead of reimplementing.
    #[test]
    fn redacted_stderr_strips_authenticated_remote_url_userinfo() {
        let output = CommandOutput {
            exit_code: Some(128),
            stdout: String::new(),
            stderr: "fatal: unable to access 'REDACTED': The requested URL returned error: 403".to_string(),
        };
        let redacted = output.redacted_stderr();
        assert!(!redacted.contains("REDACTED"), "got: {redacted}");
        assert!(redacted.contains("[REDACTED]"), "got: {redacted}");
    }

    /// Every site that builds `CommandError::Failed` from raw stderr is covered by its message, not by each caller.
    #[test]
    fn a_failed_command_error_message_hides_credentials_in_its_stderr() {
        let error = CommandError::Failed {
