            exit_code: Some(128),
            stderr: "fatal: could not read from REDACTED header Bearer REDACTED".to_string(),
        };
        let message = error.to_string();
        assert!(!message.contains("REDACTED"), "got: {message}");
        assert!(!message.contains("REDACTED"), "got: {message}");
        assert!(message.contains("exit code Some(128)"), "got: {message}");
    }
